using System.Text.Json;
using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class SolarTests
{
 public static void Run(){int checks=0;void Check(bool ok,string name){if(!ok)throw new Exception("SOLAR FAIL: "+name);checks++;Console.WriteLine("SOLAR PASS: "+name);}DemoWorld Fresh(){var w=new DemoWorld();w.NewGame(0);w.Undock();w.Player.SetStat("capacitorCapacity",100000);w.Player.Cap=w.Player.MaxCap;return w;}void Complete(DemoWorld w){for(int i=0;i<16000&&w.Transit!=null;i++)w.Update(.05f);Check(w.Transit==null,"Timed warp reaches arrival");}
 foreach(var system in DemoWorld.Systems){var c=SolarCatalog.Systems[system.Id];Check(c.Count(x=>x.Kind==CelestialKind.Sun)==1&&c.Count(x=>x.Kind==CelestialKind.Planet)>=6&&c.Any(x=>x.Kind==CelestialKind.Moon)&&c.Any(x=>x.Kind==CelestialKind.AsteroidBelt)&&c.Any(x=>x.Kind==CelestialKind.IceField)&&c.Any(x=>x.Kind==CelestialKind.GasCloud),system.Name+" populated");Check(c.All(x=>x.Position.Finite&&x.Radius>0)&&c.Where(x=>x.Kind==CelestialKind.Planet).Max(x=>x.Position.Length)>SolarCatalog.AU*5,system.Name+" real AU positions");Check(c.Count(x=>x.Kind==CelestialKind.Stargate)==system.Links.Length,system.Name+" connected gates");}
 var curve=WarpCurve.Calculate(30*SolarCatalog.AU,3,200);Check(Math.Abs(curve.AccelerationTime-9)<1&&Math.Abs(curve.CruiseTime-9)<1&&Math.Abs(curve.DecelerationTime-22)<2,"Cruiser 30 AU curve follows exponential timing");double last=0;for(double t=0;t<curve.Total;t+=.1){var sample=curve.Sample(t);if(sample.Distance+1<last||sample.Distance>curve.Distance+1||!double.IsFinite(sample.Velocity))throw new Exception("Curve discontinuity");last=sample.Distance;}Check(Math.Abs(curve.Sample(curve.Total).Distance-curve.Distance)<1,"Warp integrates to requested distance");Check(WarpCurve.Calculate(.00001*SolarCatalog.AU,3,200).CruiseTime==0,"Short warp uses reduced peak speed");Check(SolarCatalog.GridKey("aster",new(3999999,0,0))!=SolarCatalog.GridKey("aster",new(4000001,0,0)),"8,000 km boundary");
 var w=Fresh();Check(w.Targets.Any(t=>t.Kind==TargetKind.Station),"Undock has a station");var before=w.SystemPosition;double day=w.Day;Check(w.BeginWarp("aster:planet:4"),"Planet warp accepted");Check(w.Transit?.Phase=="Aligning"&&(w.SystemPosition-before).Length<1,"Warp never teleports at command");w.CancelWarp();Check(w.Transit==null&&!w.InWarp,"Alignment can be cancelled");w.BeginWarp("aster:planet:4");for(int i=0;i<4000&&!w.InWarp;i++)w.Update(.05f);Check(w.InWarp&&w.Transit!.AlignElapsed>=w.Player.Inertia*1.38,"Warp requires 75 percent speed and alignment");Check(w.LockedId.Length==0&&w.Player.Order=="warp","Locks break on actual warp");double expected=w.Transit!.Curve.Total;Complete(w);Check(w.SolarCelestial=="aster:planet:4"&&(w.SystemPosition-SolarCatalog.ById["aster:planet:4"].Anchor).Length<2501,"Planet warp lands outside surface");Check((w.Day-day)*86400>expected&&(w.Day-day)*86400<expected+30,"Warp clock follows seconds including alignment");
 w=Fresh();Check(!w.BeginWarp("station")&&w.Transit==null,"Sub-150 km warp rejected");w.EnterGrid("belt",false);Check(!w.BeginWarp("raider"),"Hostile NPC is not directly warpable");var rock=w.Targets.First(t=>t.Id=="rock");rock.Ore=37;string belt=w.SolarCelestial;w.EnterGrid("aster:planet:5",false);w.EnterGrid(belt,false);Check(w.Targets.First(t=>t.Id=="rock").Ore==37,"Returning grid preserves asteroid depletion");Check(w.Targets.Count(t=>t.Kind==TargetKind.Asteroid)>=14,"Belt contains many mineable asteroids");string bookmark=w.AddBookmark("Mine rendezvous");Check(w.Bookmarks.Single().Position==w.SystemPosition,"Bookmark captures double precision location");
 w=Fresh();string gate="aster:gate:"+w.Current.Links[0];string dest=SolarCatalog.ById[gate].Destination;Check(w.UseSolarGate(gate)&&w.SystemId=="aster"&&w.Transit!=null,"Remote jump first warps to gate");Complete(w);Check(w.SystemId==dest&&w.Targets.Any(t=>t.Kind==TargetKind.Stargate),"Arrival jumps to connected gate");w.SetDestination("rim");Check(w.Route().Count>0&&w.Route().Last()=="rim","Autopilot route crosses linked systems");
 w=Fresh();w.Player.Cap=5;w.BeginWarp("aster:planet:6");Check(w.Transit?.Partial==true,"Insufficient capacitor limits warp distance");Complete(w);Check(w.Grid=="deep_space"&&w.SystemPosition.Finite,"Partial warp arrives in a valid deep-space grid");
 w=Fresh();w.AddBookmark();w.SetDestination("rim");w.BeginWarp("aster:planet:4");for(int i=0;i<4000&&!w.InWarp;i++)w.Update(.05f);w.UpdateSolarPreview(2);var position=w.SystemPosition;w.Save();Check(File.Exists(DemoWorld.SavePath),"In-flight save written");var loaded=new DemoWorld();Check(loaded.Load()&&loaded.InWarp&&(loaded.SystemPosition-position).Length<1&&loaded.Bookmarks.Count==1&&loaded.Waypoints.Contains("rim"),"Save restores warp curve, AU position, bookmarks and route");Complete(loaded);Check(loaded.SolarCelestial=="aster:planet:4","Loaded warp completes normally");
 w=Fresh();var stationPosition=w.SystemPosition;w.Player.Position+=new Vector3(8100000,0,0);w.Update(.05f);Check(w.Grid=="deep_space"&&w.SolarGridKey==SolarCatalog.GridKey(w.SystemId,w.SystemPosition),"Crossing a real grid removes out-of-grid objects");Check(w.Targets.Count==0,"A deep-space grid does not inherit its old station");w.EnterDeepSpace(stationPosition);Check(w.Targets.Any(t=>t.Kind==TargetKind.Station),"Flying back loads the celestial grid");
 w=Fresh();w.SetDestination("rook");w.Autopilot=true;for(int i=0;i<12000&&(w.Autopilot||w.Transit!=null);i++)w.Update(.05f);Check(w.SystemId=="rook"&&!w.Autopilot&&w.Transit==null,"Autopilot warps, approaches and jumps to destination");
 w=Fresh();w.EnterGrid("aster:gate:rook",false);w.Player.Position=new(9000,0,0);Check(w.UseSolarGate("aster:gate:rook")&&w.PendingGate.Length>0,"Jump command queues gate approach");for(int i=0;i<1500&&w.SystemId=="aster";i++)w.Update(.05f);Check(w.SystemId=="rook"&&w.PendingGate.Length==0,"Approach completes gate jump automatically");
 w=Fresh();w.UtilitySites.Add(new(){Id="resolved_data",System="aster",Kind="Data",X=2,Y=.2f,Z=1,Signal=100});w.ProbeSelection="resolved_data";Check(w.WarpUtilitySite()&&w.Transit?.Phase=="Aligning","Resolved exploration signature uses timed warp");Complete(w);Check(w.Grid=="utility_site"&&w.SolarCelestial=="resolved_data"&&w.Targets.Any(t=>t.Id=="resolved_data"),"Exploration warp arrives at actual AU site");
 var raw=JsonSerializer.Serialize(new SpacePosition(SolarCatalog.AU*40,12345,9),WeaponCatalog.JsonOptions);Check(raw.Length<100&&JsonSerializer.Deserialize<SpacePosition>(raw,WeaponCatalog.JsonOptions).X==SolarCatalog.AU*40,"Position serialization is finite and lossless");Console.WriteLine(checks+" solar navigation checks passed.");}
}
